(async () => {

    const WORLD_BOOK_NAME = "洛阳扩展";

    const CONTROL_ENTRIES = [
        "洛阳总览",
        "大周通宝",
        "神策军",
        "息壤",
        "镇魔司",
        "节日",
        "角色群体设定",
        "大周法律概览",
        "钦天监",
        "安民司",
        "刑捕司",
        "环墟",
        "黑暗动乱",
        "洛阳宫城区",
        "六坊",
        "科举",
        "游仙学宫",
        "四区",
        "洛阳日常",
        "统辖司"
    ];


    async function runLuoYangHelper() {

        try {

            const vars = await TavernHelper.getVariables();

            const place =
                vars?.stat_data?.世界?.当前地点 || "";

            const enable =
                place.includes("洛阳");


            console.log(
                "[洛阳控制] 当前地点:",
                place,
                enable ? "开启" : "关闭"
            );


            const books =
                await TavernHelper.getWorldbook(WORLD_BOOK_NAME);


            if (!books) {
                console.error("[洛阳控制] 找不到世界书");
                return;
            }


            let changed = 0;


            books.entries.forEach(entry => {

                const name =
                    entry.comment ||
                    entry.name ||
                    "";

                if (CONTROL_ENTRIES.includes(name)) {

                    const old =
                        entry.disable;

                    entry.disable =
                        !enable;

                    if (old !== entry.disable) {
                        changed++;

                        console.log(
                            "[洛阳控制]",
                            name,
                            entry.disable ? "关闭" : "开启"
                        );
                    }
                }
            });


            if (changed > 0) {

                await TavernHelper.replaceWorldbook(
                    WORLD_BOOK_NAME,
                    books.entries
                );

            }


            console.log(
                "[洛阳控制] 完成，修改:",
                changed
            );


        } catch (e) {

            console.error(
                "[洛阳控制] 错误:",
                e
            );
        }
    }


    window.runLuoYangHelper = runLuoYangHelper;

    await runLuoYangHelper();

})();
